package ro.leo.visual;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Read-only providers and synthetic UI. No calls, transfers, installation or reboot. */
public final class DailyEnvironmentTests extends Instrumentation {
 int checks;Activity page;PowerManager.WakeLock wake;SharedPreferences appearance,setup;Map<String,?> oldAppearance,oldSetup;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 Object get(Object o,String n)throws Exception{for(Class<?> t=o.getClass();t!=null;t=t.getSuperclass())try{Field f=t.getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(n);}
 void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 void call(Object o,String n)throws Exception{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}
 void ui(final Runnable r){final Throwable[] error={null};runOnMainSync(new Runnable(){public void run(){try{r.run();}catch(Throwable t){error[0]=t;}}});if(error[0]!=null)throw new RuntimeException(error[0]);}
 Activity open(Class<?> c,Intent i){page=startActivitySync(i==null?new Intent(getTargetContext(),c).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK):i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();return page;}
 void close(){if(page==null)return;final Activity a=page;ui(new Runnable(){public void run(){KeypadDialog d=KeypadDialog.current();if(d!=null)d.dismiss();a.finish();}});page=null;}
 void restore(SharedPreferences p,Map<String,?> old,String... keys){SharedPreferences.Editor e=p.edit();for(String k:keys){Object v=old.get(k);if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else e.remove(k);}e.commit();}
 public void onCreate(Bundle b){start();}
 public void onStart(){Bundle result=new Bundle();final Context c=getTargetContext();appearance=c.getSharedPreferences("appearance",0);setup=c.getSharedPreferences("setup",0);oldAppearance=appearance.getAll();oldSetup=setup.getAll();try{
 wake=((PowerManager)c.getSystemService(Context.POWER_SERVICE)).newWakeLock(PowerManager.SCREEN_BRIGHT_WAKE_LOCK|PowerManager.ACQUIRE_CAUSES_WAKEUP,"Leo:DailyToolsChecks");wake.acquire(180000);
 check(GlobalSearchActivity.dialable("+40123456789")&&GlobalSearchActivity.dialable("*#06#"),"number and MMI can be handed to Phone without dialing");check(!GlobalSearchActivity.dialable("1;reboot")&&!GlobalSearchActivity.dialable("")&&!GlobalSearchActivity.dialable("https://example.com"),"non-numbers excluded from dial action");
 check(GlobalSearchActivity.matches("Muzică","muzica"),"search ignores diacritics");ArrayList<GlobalSearchActivity.Hit> apps=GlobalSearchActivity.collect(c,AppCatalog.NAMES[3],1);check(!apps.isEmpty(),"app scope finds Clock");for(GlobalSearchActivity.Hit h:apps)check(GlobalSearchActivity.inScope(h,1),"app scope excludes provider results");
 appearance.edit().putBoolean("simple-mode",false).commit();int full=AppCatalog.menuOrder(c,6).length;appearance.edit().putBoolean("simple-mode",true).commit();check(AppCatalog.menuOrder(c,6).length==6&&AppCatalog.menuOrder(c,0).length==6,"simple mode has six primary apps");check(!ShellMode.appVisible(9,true)&&ShellMode.appVisible(8,true),"simple mode keeps settings and hides Android launcher shortcut");check(full>6,"full catalog remains available");for(String k:new String[]{"simple-mode","menu-hold-help","home-type-search"})check(BackupEngine.allowed("appearance",k,"boolean"),"new mode preferences backed up");
 page=open(SettingsActivity.class,null);final SettingsActivity settings=(SettingsActivity)page;ui(new Runnable(){public void run(){try{check(((List<?>)get(settings,"listRows")).size()==6&&!(Boolean)get(settings,"categories"),"everyday settings rendered");ListView list=(ListView)get(settings,"activeList");list.performItemClick(list.getChildAt(5),5,5);check((Boolean)get(settings,"categories"),"all settings reachable without leaving simple mode");}catch(Exception e){throw new RuntimeException(e);}}});close();appearance.edit().putBoolean("simple-mode",false).commit();
 page=open(GlobalSearchActivity.class,new Intent(c,GlobalSearchActivity.class).putExtra("query","234").putExtra("home_digits",true));final GlobalSearchActivity search=(GlobalSearchActivity)page;ui(new Runnable(){public void run(){try{check(((EditText)get(search,"query")).getText().toString().equals("234"),"Home search seed kept");check((((EditText)get(search,"query")).getInputType()&android.text.InputType.TYPE_MASK_CLASS)==android.text.InputType.TYPE_CLASS_PHONE,"Home numeric T9 search keeps following digits numeric");}catch(Exception e){throw new RuntimeException(e);}}});close();
 check(SetupWizardActivity.boundedStep(-10)==0&&SetupWizardActivity.boundedStep(999)==10,"wizard eleven steps bounded");setup.edit().putInt("step",0).commit();page=open(SetupWizardActivity.class,null);final SetupWizardActivity wizard=(SetupWizardActivity)page;ui(new Runnable(){public void run(){try{wizard.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));wizard.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_RIGHT));check((Integer)get(wizard,"step")==1,"wizard right advances one step");wizard.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_LEFT));check((Integer)get(wizard,"step")==0,"wizard left returns");set(wizard,"step",7);call(wizard,"show");wizard.left.run();KeypadDialog d=KeypadDialog.current();check(d!=null&&((String[])get(d,"items")).length==2,"wizard exposes two presentation modes");d.dismiss();set(wizard,"step",10);call(wizard,"show");check(wizard.root.getChildAt(2) instanceof ProgressBar,"wizard progress visible");check(!SetupWizardActivity.summary(c).isEmpty(),"wizard summary available");}catch(Exception e){throw new RuntimeException(e);}}});close();
 check(RecoveryPackage.accepts(RecoveryPackage.BYTES,RecoveryPackage.SHA),"approved ROM metadata accepted");check(!RecoveryPackage.accepts(RecoveryPackage.BYTES,"bad")&&!RecoveryPackage.accepts(1,RecoveryPackage.SHA),"wrong hash or length rejected");check(RecoveryPackage.phone("foo androidboot.serialno=695d bar")&&!RecoveryPackage.phone("androidboot.serialno=695d-other"),"recovery target token exact");File bad=new File(c.getCacheDir(),"daily-tools-invalid.zip");try{try(FileOutputStream f=new FileOutputStream(bad)){f.write(new byte[]{1,2,3});}boolean rejected=false;try{RecoveryPackage.verify(bad);}catch(IOException expected){rejected=true;}check(rejected,"unapproved local file refused before reboot");check(!RecoveryPackage.onCard(c,bad),"internal file is not recovery SD destination");}finally{bad.delete();}
 page=open(UpdatesActivity.class,null);final UpdatesActivity updates=(UpdatesActivity)page;ui(new Runnable(){public void run(){try{check(((List<?>)get(updates,"listRows")).size()==5,"update root shows version and separated app ROM paths");call(updates,"recoveryConfirm");KeypadDialog d=KeypadDialog.current();check(d!=null&&((String[])get(d,"items")).length==2,"recovery entry requires confirmation");d.dismiss();call(updates,"show");check((Boolean)get(updates,"appPage"),"existing APK update controls retained");}catch(Exception e){throw new RuntimeException(e);}}});close();
 page=open(RecentAppsActivity.class,null);final RecentAppsActivity recent=(RecentAppsActivity)page;for(int n=0;n<75;n++){SystemClock.sleep(200);final boolean[] ready={false};ui(new Runnable(){public void run(){ready[0]=recent.left!=null;}});if(ready[0])break;}ui(new Runnable(){public void run(){try{recent.left.run();KeypadDialog d=KeypadDialog.current();check(d!=null&&((String[])get(d,"items")).length==2,"multitasking offers previous app and selected actions");d.dismiss();}catch(Exception e){throw new RuntimeException(e);}}});close();
 page=open(DownloadsActivity.class,new Intent(c,DownloadsActivity.class).putExtra("center",true));final DownloadsActivity transfers=(DownloadsActivity)page;boolean ready=false;for(int n=0;n<75;n++){SystemClock.sleep(200);final boolean[] loaded={false};ui(new Runnable(){public void run(){try{loaded[0]=get(transfers,"listRows")!=null;}catch(Exception e){throw new RuntimeException(e);}}});if(loaded[0]){ready=true;break;}}check(ready,"transfer hub loads asynchronously");ui(new Runnable(){public void run(){try{check(((List<?>)get(transfers,"listRows")).size()>=3,"hub has downloads Bluetooth and USB routes");check((Boolean)get(transfers,"centerPage"),"hub is separate from download list");}catch(Exception e){throw new RuntimeException(e);}}});close();result.putString("result","PASS "+checks+" daily-tools checks");
 }catch(Throwable t){result.putString("error",android.util.Log.getStackTraceString(t));}finally{close();restore(appearance,oldAppearance,"simple-mode","menu-hold-help","home-type-search");restore(setup,oldSetup,"step","complete");if(wake!=null&&wake.isHeld())wake.release();}finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
